		{
			title = "Обзор",
			text = [=[Теснина Ледяного Шепота — длинная долина на юге Зимних Ключей. В ней властвуют великаны Ледяного Молота, {link:ogres}огр{/link}омные существа из живого льда. Это те самые великаны, что некогда угрожали королеве ледопардов, и долину они забрали себе. По каньону разбросаны осколки чистого льда. Глубже, среди руин, {link:satyrs}сатир{/link} {link:lorax}Лоракс{/link} ходит взад и вперед и бормочет, размышляя о нарушенной сделке.]=],
		},
	},
})

Translate("ruRU", "darkwhisper-gorge", {
	title = "Теснина Зловещего Шепота",
	sections = {
		{
			title = "Обзор",
			text = [=[Теснина Зловещего Шепота лежит на южной оконечности Зимних Ключей, под высотами {link:mount-hyjal}горы Хиджал{/link}. Там снег уступает место душному воздуху и потемневшему небу. В теснине обитают демоны {link:burning-legion}Пылающего Легиона{/link}, хотя Легион был разбит у Хиджала. Демоны {link:lady-hederine}Гедерин{/link} служат своей госпоже, леди Гедерин. Ученая {link:donova-snowden}Донова Сноуден{/link} считает, что именно присутствие демонов с{link:ogres}огр{/link}евает источники Зимних Ключей далеко на севере.]=],
		},
	},
})

Translate("ruRU", "haleh", {
	title = "Халех",
	subtitle = "Матрона-защитница синих драконов",
	found = "Высокий уступ над пещерами Маззорила",
	hint = [=[Ищите ту, что говорит от имени синих драконов, высоко над пещерами Маззорила.]=],
	allegiance = "Синие драконы",
	sections = {
		{
			title = "Обзор",
			text = [=[Халех — дракон из рода синих драконов, хранителей {link:arcane-magic}тайной магии{/link}. Сородичи называют ее своей матроной-защитницей. Она обитает на высоком уступе над пещерами {link:mazthoril}Маззорил{/link}а, и добраться до нее могут лишь те, кто встанет на кобальтовые руны пещер со знаком ее рода. Она горда, холодна и нескоро начинает доверять, и редко говорит о чем-либо, кроме дел своего рода.]=],
		},
		{
			title = "Значение",
			text = [=[Аспекты повелели родам драконов не вмешиваться в дела смертных. Халех соблюдает это повеление, где может. Однако она знает, что мир не всегда это позволяет, и менее всего тогда, когда один из родов с презрением им пренебрегает. Через нее синие драконы дают свою силу смертным против черного выводка {link:deathwing}Смертокрыла{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она присматривает за {link:mazthoril}Маззорил{/link}ом, логовом синих драконов.
• Она получает чешуйку синего дракона Обби, скрытой в Вершине Черной горы, и читает то, что Обби там видела.
• Она предлагает смертным силу синих драконов против выводка {link:deathwing}Смертокрыл{/link}а.
• Она отправляет своих избранников собственной тайной силой в {link:ruins-of-andorhal}Андорал{/link}, к скульптору {link:jeziba}Джезибе{/link}.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна запись не сообщает ни возраста Халех, ни ее места среди синих драконов, ни того, как давно она несет стражу в {link:mazthoril}Маззорил{/link}е.]=],
		},
	},
	chapters = {
		{
			title = "Матрона-защитница",
			hint = "Отнесите чешуйку синего дракона в Маззорил.",
			text = [=[Из глубин Вершины Черной горы Обби послала чешуйку своей матроне. В ней Халех прочла то, что Обби видела и чувствовала в том обреченном месте: там трудились дети {link:deathwing}Смертокрыл{/link}а. Этого нельзя было допустить. Но поскольку гора укрывает дракона Нефариана, синие драконы не могли ударить по нему сами. Они могли лишь наделить силой тех, кто на это решится.]=],
		},
		{
			title = "Гнев синих драконов",
			hint = "Примите дар синих драконов.",
			text = [=[Халех предупредила, что дорога полна опасностей, и попросила сделать выбор свободно. Тем, кто согласился, она предложила силу собственной магии, чтобы ускорить их путь. Она открыла дорогу в Чумные земли и отправила их к смертному Джезибе, назвав его мудрым, как древние.]=],
		},
		{
			title = "Глаз дракона",
			hint = "Принесите синим драконам осколок глаза черного дракона.",
			text = [=[Осколок, принесенный ей из {link:stormwind-city}Штормград{/link}а, сразу вызвал у нее отвращение. Это была чешуйка матери черного выводка, Ониксии, зачарованная так, чтобы стать ключом к ее логову, а потом разбитая. Халех могла восстановить ее, но только с кровью воителя черных драконов: это генерал Драккисат, который правит драконорожденными Нефариана в Вершине Черной горы. Когда кровь была доставлена, она выковала Амулет Драконьего Огня. С ним обереги, которые {link:onyxia}Ониксия{/link} наложила в Драконьих топях {link:dustwallow-marsh}Пылевых топей{/link}, не могли преградить путь.]=],
		},
	},
	mentions = {
		{ text = "Матрона-защитница" },
		{ text = "Гнев синих драконов" },
		{ text = "Гнев синих драконов, путь к скульптору Джезибе" },
		{ text = "Глаз дракона" },
		{ text = "Амулет Драконьего Огня" },
	},
	bonds = {
		{ id = "jeziba", name = "Джезиба", note = "она посылает к нему героев" },
		{ id = "awbee", name = "Обби", note = "синий дракон, которая служит ей в Вершине Черной горы" },
	},
})

Translate("ruRU", "donova-snowden", {
	title = "Донова Сноуден",
	subtitle = "Ученая у горячих источников",
	found = "У Источников Ледяного Пламени",
	hint = [=[Ищите ученую, которая стоит лагерем у горячих источников на западе.]=],
	allegiance = "Друзья: Линкен и Кракл",
	aliases = { "Донова" },
	sections = {
		{
			title = "Обзор",
			text = [=[Донова Сноуден пришла в {link:winterspring}Зимние Ключи{/link}, чтобы узнать тайну Источников Ледяного Пламени, где теплая вода парит в краю без вулканов. Она до сих пор стоит лагерем рядом с ними. Она терпелива, любознательна и добра и верит, что холодные земли хранят больше тайн, чем любая теплая. Ее изыскания привели ее к делу более темному, чем она ожидала: к безумию племени Зимней Спячки.]=],
		},
		{
			title = "Значение",
			text = [=[Донова первой проследила безумие племени Зимней Спячки до его источника. Благодаря ее трудам стало известно, что племя пьет огненную воду, сваренную из скверны Оскверненного леса, и что сами горячие источники, возможно, обязаны своим теплом демонам.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она изучает {link:frostfire-hot-springs}Источники Ледяного Пламени{/link} и их странную воду.
• Она узнает, что {link:winterfall-furbolgs}племя Зимней Спячки{/link} очищает в источниках свою огненную воду.
• Она находит демонов Теснины Зловещего Шепота и считает их причиной тепла источников.
• Она хранит меч для своего друга {link:linken}Линкен{/link}а и знает, как его можно завершить.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Игра не говорит, откуда пришла Донова и какому ордену она служит, если служит вообще.]=],
		},
	},
	chapters = {
		{
			title = "Огненная вода Зимней Спячки",
			hint = "Принесите ученой флягу, оброненную фурболгом Зимней Спячки.",
			text = [=[Фляга была пуста, если не считать нескольких капель светящейся зеленой жидкости. Донова сразу узнала в ней нечто похожее на слизь {link:felwood}Оскверненного леса{/link}. След привел к стоянкам племени Мертвого Леса, а оттуда — к ядовитым ужасам Железнолесья. Когда она смешала яд с водой источника, он утратил смертоносность, но сохранил власть над теми, кто его пил. Теперь она поняла, почему {link:winterfall-furbolgs}племя Зимней Спячки{/link} стережет источники: они нужны ему, чтобы делать огненную воду.]=],
		},
		{
			title = "Верховный вождь",
			hint = "Покончите с тем, кто повелевает племенем Зимней Спячки.",
			text = [=[Племя Зимней Спячки никогда не было склонно к насилию, сказала Донова. Только их вождь мог направить их на этот путь. Она не надеялась исправить содеянное, но верила, что без предводителя они не падут еще ниже. Вождь носил при себе журнал, написанный знаками столь грубыми, что она не смогла его прочесть. Она отправила его на юг, друиду {link:kelek-skykeeper}Келек{/link}у Хранителю Небес, который хорошо знает {link:furbolgs}фурболг{/link}ов Оскверненного леса.]=],
		},
		{
			title = "Источник источников",
			hint = [=[Отправляйтесь на юг, туда, где воздух густеет, а небо темнеет.]=],
			text = [=[Донова не верила, что источники с{link:ogres}огр{/link}евает одна лишь земля. Она послала путника на дальний юг Зимних Ключей, где воздух становится душным, а небо темнеет. Там лежала {link:darkwhisper-gorge}Теснина Зловещего Шепота{/link} с ее демонами. Теперь Донова следит за источниками, ожидая новых признаков их влияния.]=],
		},
	},
	mentions = {
		{ text = "Беда в Зимних Ключах!, от Мегги Пеппинрокер" },
		{ text = "Угроза Зимней Спячки" },
		{ text = "Огненная вода Зимней Спячки" },
		{ text = "Во власти скверны" },
		{ text = "Загадочная слизь" },
		{ text = "Ядовитые ужасы" },
		{ text = "Гонцы Зимней Спячки" },
		{
			text = [=[{link:high-chief-winterfall}Верховный вождь Зимней Спячки{/link}]=],
		},
		{ text = "Последний кусочек" },
		{ text = "Слова верховного вождя" },
		{ text = "Новые источники, от {link:krakle}Кракл{/link}а" },
		{ text = "Странные источники" },
		{ text = "Это тайна для всех" },
		{ text = "Эликсир Видере" },
		{ text = "Встреча у могилы" },
	},
	bonds = {
		{ id = "high-chief-winterfall", name = "Верховный вождь Зимней Спячки", note = "вождь, которого она хотела остановить" },
		{ id = "kelek-skykeeper", name = "Келек Хранитель Небес", note = "читает для нее журнал вождя" },
		{ id = "linken", name = "Линкен", note = "ее друг, потерявший память" },
		{ id = "krakle", name = "Кракл", note = "ее друг в Ун'Горо" },
	},
})

