Translate("ruRU", "witch-doctor-mau-ari", {
	title = "Знахарка Мау'ари",
	subtitle = "Знахарка Круговзора",
	found = "Круговзор",
	hint = [=[Найдите в Круговзоре знахарку-тролля, которая знает, зачем вы пришли.]=],
