	aliases = { "Мау'ари" },
	sections = {
		{
			title = "Обзор",
			text = [=[Мау'ари — знахарка-тролль, поселившаяся в {link:everlook}Круговзор{/link}е. Она говорит о себе, называя себя по имени, и уверяет, что всегда знает, чего хочет посетитель, еще до того, как он это скажет. Она учит, что каждое существо несет в себе духовную силу, называемую э'ко. С амулетом ее работы эту силу можно поймать, а с ее заклинаниями она становится джуджу.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она делает амулет «Тайник Мау'ари» из осколков льда великанов Ледяного Молота.
• Она превращает э'ко ледопардов, йети, совухов и {link:furbolgs}фурболг{/link}ов в джуджу.
• Когда-то она за плату сделала талисман на удачу для путника {link:harlo-barnaby}Харло{/link} Вигглсворта.]=],
		},
	},
	mentions = {
		{
			text = [=[Немного удачи, от {link:harlo-barnaby}Харло{/link} Вигглсворта]=],
		},
		{ text = "Да пребудет с вами удача" },
		{ text = "Тайник Мау'ари" },
		{ text = "Э'ко ледопардов" },
		{ text = "Э'ко Зимней Спячки" },
		{ text = "Э'ко совухов" },
	},
})

