Translate("ruRU", "lorax", {
	title = "Лоракс",
	subtitle = "Сатир демонической кузни",
	found = "Руины на юге Теснины Ледяного Шепота",
	hint = [=[Ищите сатира, который расхаживает среди руин в южной теснине.]=],
	allegiance = "Нет",
	sections = {
		{
			title = "Обзор",
			text = [=[Лоракс — {link:satyrs}сатир{/link}, стоящий среди руин на юге Зимних Ключей. По его собственным словам, его дни идут медленным кругом скорби, ненависти и козней. Он владеет искусством демонической кузни. Когда-то он заключил сделку: научить этому искусству {link:orcs}орк{/link}а из клана Черной горы, Горалука Треснувшую {link:nak}Нак{/link}овальню, в обмен на его душу. Горалук забрал невыкованный нагрудник и бежал в Вершину Черной горы, не расплатившись.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он предлагает свои знания всякому, кто взыщет душу, которую ему задолжали.
• Он дает напитанную скверной пику, чтобы она выпила душу Горалука, когда тот будет умирать.]=],
		},
	},
	chapters = {
		{
			title = "Нарушенная сделка",
			hint = "Выслушайте рассказ сатира и взыщите его долг.",
			text = [=[Душа, любая душа, в эти времена чего-то стоит, сказал Лоракс, — даже душа {link:orcs}орк{/link}а из клана Черной горы. Когда пика вернулась, запятнанная душой должника, а с ней и украденный нагрудник, {link:satyrs}сатир{/link} исполнил свою часть договора.]=],
		},
	},
	mentions = {
		{ text = "Рассказ Лоракса" },
		{ text = "Демоническая кузня" },
	},
})

Translate("ruRU", "ranshalla", {
