	bonds = {
		{ id = "erelas-ambersky", name = "Эрелас Янтарное Небо", note = "послал ее в Зимние Ключи" },
		{ id = "fandral-staghelm", name = "Фэндрал Олений Шлем", note = "выслушал то, что она нашла" },
	},
})

