Translate("ruRU", "winterfall-furbolgs", {
	title = "Фурболги Зимней Спячки",
	aliases = { "Зимняя Спячка", "племя Зимней Спячки" },
	sections = {
		{
			title = "Обзор",
			text = [=[Племя Зимней Спячки — это племя {link:furbolgs}фурболгов{/link} Зимних Ключей. Оно не было склонно к насилию и долго было союзником Древобрюхов. Это изменилось. Верховный вождь предъявил племени странные требования, и теперь оно набрасывается на всякого, кто подойдет близко, будь то зверь или путник, эльф или гоблин. Племя держит деревню в холмах к востоку от {link:everlook}Круговзор{/link}а и стоянки близ Источников Ледяного Пламени.]=],
		},
		{
			title = "Огненная вода",
			text = [=[У безумия есть источник. Гонцы племени ходят через {link:timbermaw-hold}Крепость Древобрюхов{/link} к {link:furbolgs}фурболг{/link}ам Мертвого Леса в {link:felwood}Оскверненном лесу{/link}, которых самих свела с ума скверна. Обратно они несут зеленое варево, сделанное из яда ядовитых ужасов Железнолесья. Само по себе оно убило бы их. Смешанное с водой горячих источников, оно теряет смертоносность, но сохраняет силу, и те, кто его пьет, становятся крупнее и свирепее. Вот почему племя Зимней Спячки так яростно стережет источники. Фурболги все еще носят бусы духов, чтобы отгонять злых духов, но бусы не спасли их от того, чем они стали.]=],
		},
	},
})

Translate("ruRU", "crystal-of-zin-malor", {
	title = "Кристалл Зин-Малор",
	sections = {
		{
			title = "Обзор",
			text = [=[Кристалл Зин-Малор — реликвия, способная вмещать великие тайные силы и повелевать ими. Овладеть им могут только истинно достойные, и надеяться на это могла бы лишь горстка сильнейших магов. Он носит имя {link:temple-of-zin-malor}Храма Зин-Малор{/link}, который ныне лежит в руинах в {link:azshara}Азшаре{/link}. В древние дни высокорожденные {link:lake-kel-theril}Кел'Терил{/link}а похитили его, намереваясь вытянуть его силу для себя. При этой попытке кристалл разлетелся на части в мощном взрыве, и его осколки ушли под лед озера. Высокорожденные были прокляты оставаться там вечно, все еще ища осколки.]=],
		},
		{
			title = "Воссозданный",
			text = [=[В наши дни кирка {link:dwarves}дворф{/link}а пробила лед и подняла четыре осколка. Высшая эльфийка {link:aurora-skycaller}Аврора Призывательница Небес{/link} узнала их. С помощью священных писаний высокорожденных, добытых в разрушенном храме в Азшаре, она восстановила кристалл. Его показали духу {link:lake-kel-theril}Кел'Терил{/link}а, который раскаялся в давнем преступлении, и этот дух обрел покой. Кристалл никогда не мог вернуться в свой храм. {link:wynd-nightchaser}Винд Ночной Преследователь{/link} из Деревни {link:starfall-village}Звездопад{/link}а отправил его в {link:darnassus}Дарнасс{/link}, верховному друиду {link:fandral-staghelm}Фэндрал{/link}у Оленьему Шлему, который похвалил тех, кто его нес, за то, что они не попытались воспользоваться им сами.]=],
		},
	},
})
